import math


class CentroidIndex:
    def __init__(self, group_count, tolerance=1e-9, max_iterations=100):
        if isinstance(group_count, bool) or not isinstance(group_count, int):
            raise TypeError('group_count must be an integer')
        if group_count <= 0:
            raise ValueError('group_count must be positive')
        if isinstance(max_iterations, bool) or not isinstance(max_iterations, int):
            raise TypeError('max_iterations must be an integer')
        if max_iterations <= 0:
            raise ValueError('max_iterations must be positive')
        if isinstance(tolerance, bool) or not isinstance(tolerance, (int, float)):
            raise TypeError('tolerance must be numeric')
        if not math.isfinite(tolerance) or tolerance < 0:
            raise ValueError('tolerance must be finite and non-negative')
        self.group_count = group_count
        self.tolerance = float(tolerance)
        self.max_iterations = max_iterations
        self._centers = None
        self._dimension = None

    @staticmethod
    def _prepare(points, allow_empty, expected_dimension=None):
        if isinstance(points, (str, bytes)):
            raise TypeError('points must be an iterable of vectors')
        try:
            raw_points = list(points)
        except TypeError as exc:
            raise TypeError('points must be iterable') from exc
        if not raw_points and not allow_empty:
            raise ValueError('points must not be empty')
        prepared = []
        dimension = expected_dimension
        for raw in raw_points:
            if isinstance(raw, (str, bytes)):
                raise TypeError('each point must be iterable')
            try:
                values = list(raw)
            except TypeError as exc:
                raise TypeError('each point must be iterable') from exc
            if not values:
                raise ValueError('points must not be empty vectors')
            if dimension is None:
                dimension = len(values)
            if len(values) != dimension:
                raise ValueError('inconsistent point dimensions')
            point = []
            for value in values:
                if isinstance(value, bool) or not isinstance(value, (int, float)):
                    raise TypeError('coordinates must be numeric')
                if not math.isfinite(value):
                    raise ValueError('coordinates must be finite')
                point.append(float(value))
            prepared.append(point)
        return prepared, dimension

    @staticmethod
    def _nearest(point, centers):
        return min(
            range(len(centers)),
            key=lambda index: sum((a - b) ** 2 for a, b in zip(point, centers[index])),
        )

    def fit(self, points):
        prepared, dimension = self._prepare(points, False)
        centers = []
        for point in prepared:
            if point not in centers:
                centers.append(point[:])
                if len(centers) == self.group_count:
                    break
        if len(centers) < self.group_count:
            raise ValueError('not enough distinct points')
        for _ in range(self.max_iterations):
            groups = [[] for _ in centers]
            for point in prepared:
                groups[self._nearest(point, centers)].append(point)
            updated = []
            for center, group in zip(centers, groups):
                if group:
                    updated.append([
                        sum(point[d] for point in group) / len(group)
                        for d in range(dimension)
                    ])
                else:
                    updated.append(center[:])
            change = max(
                abs(old[d] - new[d])
                for old, new in zip(centers, updated)
                for d in range(dimension)
            )
            centers = updated
            if change <= self.tolerance:
                break
        self._centers = [center[:] for center in centers]
        self._dimension = dimension
        return self

    def predict(self, points):
        if self._centers is None:
            raise RuntimeError('model has not been fitted')
        prepared, _ = self._prepare(points, True, self._dimension)
        return [self._nearest(point, self._centers) for point in prepared]

    @property
    def centers(self):
        if self._centers is None:
            raise RuntimeError('model has not been fitted')
        return self._centers

